style.css:
@-moz-document domain("youtube.com") {
:root {
  --my-wine: #4b101b;
  --my-maroon: #641c2a;
  --my-red: #8d3545;
  --my-rose: #c18b89;
  --my-cream: #e5cba9;
  --my-dark: #260b11;
}

ytd-app {
  background: var(--my-dark) !important;
  color: var(--my-cream) !important;
}

#content,
ytd-browse,
ytd-watch-flexy {
  background: var(--my-dark) !important;
}

ytd-masthead {
  background: var(--my-wine) !important;
}

ytd-guide-renderer,
ytd-mini-guide-renderer {
  background: var(--my-dark) !important;
}

ytd-searchbox {
  border: 1px solid var(--my-rose) !important;
  border-radius: 24px !important;
  overflow: hidden !important;
}

#container.ytd-searchbox {
  background: var(--my-wine) !important;
}

#search-icon-legacy {
  background: var(--my-maroon) !important;
}

ytd-rich-item-renderer,
ytd-video-renderer {
  background: var(--my-wine) !important;
  border-radius: 14px !important;
}

yt-chip-cloud-chip-renderer {
  background: var(--my-maroon) !important;
  border-radius: 20px !important;
}

yt-chip-cloud-chip-renderer[selected] {
  background: var(--my-cream) !important;
  color: var(--my-dark) !important;
}

a,
#video-title {
  color: var(--my-cream) !important;
}

::-webkit-scrollbar {
  width: 8px !important;
}

::-webkit-scrollbar-thumb {
  background: var(--my-red) !important;
  border-radius: 10px !important;
}
}
